-- Report ID : RPT_011
-- Report    : Item Store Cost And Price
-- Module    : Other
-- Source    : Oracle RMS / MFCS RDS Views
-- Generated : Extracted from DVA file
--------------------------------------------------------------------------------

SELECT     im.DEPT                                             AS dept_no,     d.DEPT_NAME                                         AS dept_name,     im.CLASS                                            AS class_no,     c.CLASS_NAME                                        AS class_name,     im.SUBCLASS                                         AS subclass_no,     sc.SUB_NAME                                         AS subclass_name,     im.ITEM                                             AS item_id,     im.ITEM_DESC                                        AS item_description,     im.ITEM_NUMBER_TYPE                                 AS item_number_type,     im.STANDARD_UOM                                     AS unit_of_measure,     im.SELLABLE_IND                                     AS sellable_ind,     im.ORDERABLE_IND                                    AS orderable_ind,     im.ITEM_LEVEL                                       AS item_level,     im.TRAN_LEVEL                                       AS transaction_level,      il.LOC                                              AS store_id,     st.STORE_NAME                                       AS store_name,     st.STORE_TYPE                                       AS store_type,     CASE st.STORE_TYPE         WHEN 'C' THEN 'Company Store'         WHEN 'F' THEN 'Franchise Store'         ELSE st.STORE_TYPE     END                                                 AS store_type_desc,     st.CURRENCY_CODE                                    AS store_currency,     il.STATUS                                           AS item_loc_status,     CASE il.STATUS         WHEN 'A' THEN 'Active'         WHEN 'C' THEN 'Discontinued'         WHEN 'I' THEN 'Inactive'         WHEN 'D' THEN 'Delete'     END                                                 AS item_loc_status_desc,      isc.SUPPLIER                                        AS primary_supplier_id,     sp.SUP_NAME                                         AS primary_supplier_name,     isc.UNIT_COST                                       AS supplier_unit_cost,     isc.ORIGIN_COUNTRY_ID                               AS origin_country,      ils.AV_COST                                         AS store_average_cost,     ils.UNIT_COST                                       AS store_unit_cost,      il.UNIT_RETAIL                                      AS current_store_retail,     il.SELLING_UNIT_RETAIL                              AS selling_unit_retail,     il.SELLING_UOM                                      AS selling_uom,      ph.SELLING_UNIT_RETAIL                              AS current_active_retail,     ph.MULTI_UNITS                                      AS multi_units,     ph.MULTI_UNIT_RETAIL                                AS multi_unit_retail,     ph.TRAN_TYPE                                        AS price_tran_type,     ph.REASON                                           AS price_change_reason,     ph.ACTION_DATE                                      AS price_action_date,      fc.PRICING_COST                                     AS franchise_pricing_cost,     fc.NET_COST                                         AS franchise_net_cost,     fc.BASE_COST                                        AS franchise_base_cost,     fc.ACTIVE_DATE                                      AS franchise_cost_active_date,     fc.CALC_DATE                                        AS franchise_cost_calc_date,      CASE         WHEN il.UNIT_RETAIL > 0 AND ils.AV_COST IS NOT NULL         THEN ROUND(((il.UNIT_RETAIL - ils.AV_COST) / il.UNIT_RETAIL) * 100, 2)     END                                                 AS gross_margin_pct,      CASE         WHEN il.SELLING_UNIT_RETAIL > 0 AND fc.PRICING_COST IS NOT NULL         THEN ROUND(((il.SELLING_UNIT_RETAIL - fc.PRICING_COST)                    / il.SELLING_UNIT_RETAIL) * 100, 2)     END                                                 AS franchise_margin_pct,      ils.STOCK_ON_HAND                                   AS store_soh,      TRUNC(SYSDATE)                                      AS report_date  FROM     MFCS_RDS.RDS_WV_ITEM_LOC              il     JOIN  MFCS_RDS.RDS_WV_ITEM_MASTER     im   ON  il.ITEM              = im.ITEM                                               AND  im.TRAN_LEVEL         = im.ITEM_LEVEL      JOIN  MFCS_RDS.RDS_WV_DEPS            d    ON  im.DEPT              = d.DEPT     JOIN  MFCS_RDS.RDS_WV_CLASS           c    ON  im.DEPT              = c.DEPT                                               AND  im.CLASS              = c.CLASS     JOIN  MFCS_RDS.RDS_WV_SUBCLASS        sc   ON  im.DEPT              = sc.DEPT                                               AND  im.CLASS              = sc.CLASS                                               AND  im.SUBCLASS           = sc.SUBCLASS      JOIN  MFCS_RDS.RDS_WV_STORE           st   ON  il.LOC               = st.STORE      LEFT JOIN MFCS_RDS.RDS_WV_ITEM_LOC_SOH  ils                                              ON  il.ITEM                = ils.ITEM                                              AND il.LOC                 = ils.LOC                                              AND ils.LOC_TYPE           = 'S'      LEFT JOIN MFCS_RDS.RDS_WV_ITEM_SUPP_COUNTRY  isc                                              ON  im.ITEM                = isc.ITEM                                              AND isc.PRIMARY_SUPP_IND   = 'Y'                                              AND isc.PRIMARY_COUNTRY_IND = 'Y'     LEFT JOIN MFCS_RDS.RDS_WV_SUPS         sp   ON  isc.SUPPLIER        = sp.SUPPLIER      LEFT JOIN MFCS_RDS.RDS_WV_PRICE_HIST   ph   ON  il.ITEM             = ph.ITEM                                               AND  il.LOC                = ph.LOC                                               AND  ph.TRAN_TYPE          = 22                                               AND  ph.ACTION_DATE        = (                                                     SELECT MAX(ph2.ACTION_DATE)                                                     FROM   MFCS_RDS.RDS_WV_PRICE_HIST ph2                                                     WHERE  ph2.ITEM      = il.ITEM                                                     AND    ph2.LOC       = il.LOC                                                     AND    ph2.TRAN_TYPE = 22                                                     AND    ph2.ACTION_DATE <= TRUNC(SYSDATE)                                                )      LEFT JOIN MFCS_RDS.RDS_WV_FUTURE_COST  fc   ON  il.ITEM             = fc.ITEM                                               AND  il.LOC                = fc.LOCATION                                               AND  fc.LOC_TYPE           = 'S'                                               AND  fc.ACTIVE_DATE        <= TRUNC(SYSDATE)                                               AND  (fc.CALC_DATE IS NULL                                                    OR fc.CALC_DATE      >= TRUNC(SYSDATE))  WHERE 1=1 and     il.STATUS           IN ('A', 'C')     AND im.SELLABLE_IND  = 'Y'     AND il.LOC_TYPE      = 'S'  ORDER BY     d.DEPT_NAME,     c.CLASS_NAME,     sc.SUB_NAME,     im.ITEM_DESC,     st.STORE_NAME